"""Ascend fused-list executor for the ternary ``_foreach_*`` scalar operators.

``addcmul``/``addcdiv`` take three paired tensor lists and one scalar per entry:
``self[i] + value * tensor1[i] * tensor2[i]`` (multiply) or
``self[i] + value * tensor1[i] / tensor2[i]`` (divide).

A run of consecutive homogeneous entries -- same dtype, shape, element count and
all contiguous -- is executed by one launch with grid ``(slots, blocks)``.  Each
slot is a block-uniform branch, so all four pointers stay statically typed and
the compiler keeps its access width; the per-entry scalar travels as a kernel
argument.  Non-contiguous or broadcast entries fall back to a stride-decomposed
per-entry kernel.
"""

import torch
import triton
import triton.language as tl

_MODE_MUL = 0
_MODE_DIV = 1

_MAX_SLOTS = 16
_MAX_GRID = 65535
_MAX_DIMS = 8
# Four tiles of BLOCK elements (three reads, one write) must fit the 192 KiB
# UB, and fp32 tiles are twice as large as 16-bit ones.
_BLOCK_16 = 4096
_BLOCK_32 = 2048
_BLOCK_STRIDED = 512


def _block_for(dtype):
    return _BLOCK_16 if dtype.itemsize <= 2 else _BLOCK_32


