@triton.jit
def _tern_math(s, a, b, value, MODE: tl.constexpr, INTMATH: tl.constexpr):
    # ``MODE`` is compared against literals: this Triton build refuses to read a
    # plain module global from inside a kernel.
    if INTMATH:
        return s + value * a * b
    if MODE == 0:  # _MODE_MUL
        return s + value * a * b
    return s + (value * a) / b


@triton.jit
def _tern_tile(
    sp,
    ap,
    bp,
    op,
    n,
    value,
    pid,
    MODE: tl.constexpr,
    EVEN: tl.constexpr,
    INTMATH: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        if INTMATH:
            s = tl.load(sp + offs).to(tl.int64)
            a = tl.load(ap + offs).to(tl.int64)
            b = tl.load(bp + offs).to(tl.int64)
        else:
            s = tl.load(sp + offs).to(tl.float32)
            a = tl.load(ap + offs).to(tl.float32)
            b = tl.load(bp + offs).to(tl.float32)
        r = _tern_math(s, a, b, value, MODE, INTMATH)
        tl.store(op + offs, r.to(op.dtype.element_ty))
    else:
        m = offs < n
        if INTMATH:
            s = tl.load(sp + offs, mask=m, other=0).to(tl.int64)
            a = tl.load(ap + offs, mask=m, other=0).to(tl.int64)
            b = tl.load(bp + offs, mask=m, other=0).to(tl.int64)
        else:
            s = tl.load(sp + offs, mask=m, other=0.0).to(tl.float32)
            a = tl.load(ap + offs, mask=m, other=0.0).to(tl.float32)
            b = tl.load(bp + offs, mask=m, other=1.0).to(tl.float32)
        r = _tern_math(s, a, b, value, MODE, INTMATH)
        tl.store(op + offs, r.to(op.dtype.element_ty), mask=m)


