@triton.jit
def _tern_flat(
    sp,
    ap,
    bp,
    op,
    n,
    value,
    MODE: tl.constexpr,
    INTMATH: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """One contiguous entry, grid-strided so the 65535-program cap is moot."""
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    i = pid * BLOCK
    while i < n:
        offs = i + tl.arange(0, BLOCK)
        m = offs < n
        if INTMATH:
            s = tl.load(sp + offs, mask=m, other=0).to(tl.int64)
            a = tl.load(ap + offs, mask=m, other=0).to(tl.int64)
            b = tl.load(bp + offs, mask=m, other=0).to(tl.int64)
        else:
            s = tl.load(sp + offs, mask=m, other=0.0).to(tl.float32)
            a = tl.load(ap + offs, mask=m, other=0.0).to(tl.float32)
            b = tl.load(bp + offs, mask=m, other=1.0).to(tl.float32)
        r = _tern_math(s, a, b, value, MODE, INTMATH)
        tl.store(op + offs, r.to(op.dtype.element_ty), mask=m)
        i += step


@triton.jit
def _tern_strided(
    sp,
    ap,
    bp,
    op,
    n,
    value,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    sa0,
    sa1,
    sa2,
    sa3,
    sa4,
    sa5,
    sa6,
    sa7,
    aa0,
    aa1,
    aa2,
    aa3,
    aa4,
    aa5,
    aa6,
    aa7,
    ba0,
    ba1,
    ba2,
    ba3,
    ba4,
    ba5,
    ba6,
    ba7,
    MODE: tl.constexpr,
    INTMATH: tl.constexpr,
    NDIM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Stride-decomposed indexing for one entry; the output is contiguous."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    rem = offs
    dims = (d0, d1, d2, d3, d4, d5, d6, d7)
    sst = (sa0, sa1, sa2, sa3, sa4, sa5, sa6, sa7)
    ast = (aa0, aa1, aa2, aa3, aa4, aa5, aa6, aa7)
    bst = (ba0, ba1, ba2, ba3, ba4, ba5, ba6, ba7)
    so = tl.zeros([BLOCK], dtype=tl.int32)
    ao = tl.zeros([BLOCK], dtype=tl.int32)
    bo = tl.zeros([BLOCK], dtype=tl.int32)
    for k in tl.static_range(NDIM):
        c = rem % dims[k]
        rem = rem // dims[k]
        so += c * sst[k]
        ao += c * ast[k]
        bo += c * bst[k]
    if INTMATH:
        s = tl.load(sp + so, mask=m, other=0).to(tl.int64)
        a = tl.load(ap + ao, mask=m, other=0).to(tl.int64)
        b = tl.load(bp + bo, mask=m, other=0).to(tl.int64)
    else:
        s = tl.load(sp + so, mask=m, other=0.0).to(tl.float32)
        a = tl.load(ap + ao, mask=m, other=0.0).to(tl.float32)
        b = tl.load(bp + bo, mask=m, other=1.0).to(tl.float32)
    r = _tern_math(s, a, b, value, MODE, INTMATH)
    tl.store(op + offs, r.to(op.dtype.element_ty), mask=m)


