def _pad(vals, fill=1):
    out = list(vals)
    return out + [fill] * (_MAX_DIMS - len(out))


def _launch_strided(mode, s, a, b, o, value, intmath):
    n = s.numel()
    nd = s.dim()
    if nd > _MAX_DIMS:
        raise ValueError("foreach: tensor rank above supported maximum")
    # Innermost axis first: the flat index is decomposed from the inside out.
    d = _pad(list(reversed(list(s.shape))))
    ss = _pad(list(reversed(list(s.stride()))), 0) if nd else [1] * _MAX_DIMS
    aa = _pad(list(reversed(list(a.stride()))), 0) if nd else [1] * _MAX_DIMS
    bb = _pad(list(reversed(list(b.stride()))), 0) if nd else [1] * _MAX_DIMS
    _tern_strided[(triton.cdiv(n, _BLOCK_STRIDED),)](
        s,
        a,
        b,
        o,
        n,
        value,
        *d,
        *ss,
        *aa,
        *bb,
        MODE=mode,
        INTMATH=intmath,
        NDIM=nd,
        BLOCK=_BLOCK_STRIDED,
    )


def _launch_single(mode, s, a, b, o, value, intmath):
    n = s.numel()
    if n == 0:
        return
    if (
        s.is_contiguous()
        and a.is_contiguous()
        and b.is_contiguous()
        and o.is_contiguous()
        and a.numel() == n
        and b.numel() == n
        and a.shape == s.shape
        and b.shape == s.shape
    ):
        blk = _block_for(s.dtype)
        grid = (min(triton.cdiv(n, blk), _MAX_GRID),)
        _tern_flat[grid](s, a, b, o, n, value, MODE=mode, INTMATH=intmath, BLOCK=blk)
        return
    _launch_strided(mode, s, a, b, o, value, intmath)


def _launch_fused(mode, ss, aa, bb, oo, values, intmath, block):
    slots = len(ss)
    n = ss[0].numel()
    blocks = triton.cdiv(n, block)
    even = n % block == 0
    pad = _MAX_SLOTS - slots
    # The kernel signature groups one block per operand (all ``s`` pointers,
    # then all ``a``, ...) rather than interleaving the slots.
    ss = list(ss) + [ss[0]] * pad
    aa = list(aa) + [aa[0]] * pad
    bb = list(bb) + [bb[0]] * pad
    oo = list(oo) + [oo[0]] * pad
    ptrs = ss + aa + bb + oo
    vals = list(values) + [values[0]] * pad
    _tern_fused[(blocks,)](
        *ptrs,
        *vals,
        n,
        MODE=mode,
        EVEN=even,
        INTMATH=intmath,
        SLOTS=slots,
        BLOCK=block,
    )


def _simple(s, a, b, o, n, dtype):
    return (
        s.dtype is dtype
        and a.dtype is dtype
        and b.dtype is dtype
        and s.is_contiguous()
        and a.is_contiguous()
        and b.is_contiguous()
        and o.is_contiguous()
        and s.numel() == n
        and a.numel() == n
        and b.numel() == n
        and o.numel() == n
        and a.shape == s.shape
        and b.shape == s.shape
    )


def launch(mode, ss, aa, bb, oo, values):
    """Run ``oo[i] = ss[i] <op> values[i] * aa[i] (*|/) bb[i]``.

    ``oo[i]`` may alias ``ss[i]`` (the in-place forms do exactly that).
    """
    count = len(ss)
    i = 0
    while i < count:
        s = ss[i]
        n = s.numel()
        if n == 0:
            i += 1
            continue
        dtype = s.dtype
        intmath = not dtype.is_floating_point
        value = values[i]
        block = _block_for(dtype)
        if not _simple(s, aa[i], bb[i], oo[i], n, dtype):
            _launch_single(mode, s, aa[i], bb[i], oo[i], value, intmath)
            i += 1
            continue
        j = i + 1
        while j < count and (j - i) < _MAX_SLOTS:
            if not _simple(ss[j], aa[j], bb[j], oo[j], n, dtype):
                break
            j += 1
        blocks = triton.cdiv(n, block)
        if blocks <= _MAX_GRID:
            _launch_fused(
                mode,
                ss[i:j],
                aa[i:j],
                bb[i:j],
                oo[i:j],
                values[i:j],
                intmath,
                block,
            )
        else:
            for k in range(i, j):
                _launch_single(mode, ss[k], aa[k], bb[k], oo[k], values[k], intmath)
        i = j


