def scalar_value(v):
    if isinstance(v, torch.Tensor):
        if v.numel() != 1:
            raise RuntimeError("foreach: value tensor must hold one element")
        return v.item()
    return v


def normalize_values(value, count, dtypes):
    """Expand ``value`` to one Python scalar per entry, wrapped for ``dtypes``.

    Integral operands require an integral scalar (ATen refuses a fractional one)
    and are passed to the kernel as ints so the arithmetic stays integral.
    """
    if isinstance(value, torch.Tensor):
        if value.numel() == 1:
            value = value.item()
        elif value.numel() == count:
            value = list(value.reshape(-1).tolist())
        else:
            raise RuntimeError(
                "Tensor list must have same number of elements as scalar list."
            )
    if isinstance(value, (list, tuple)):
        vals = [scalar_value(v) for v in value]
        if len(vals) != count:
            raise RuntimeError(
                "Tensor list must have same number of elements as scalar list, "
                f"got {count} and {len(vals)}"
            )
    else:
        vals = [value] * count
    out = []
    for v, dt in zip(vals, dtypes):
        if dt.is_floating_point or dt.is_complex:
            out.append(float(v))
        else:
            fv = float(v)
            if fv != int(fv):
                raise RuntimeError(
                    "For integral input tensors, argument alpha must not be "
                    "a floating point number."
                )
            out.append(int(fv))
    return out


def check_tensor_list(tensors, name="self"):
    if type(tensors) is list and tensors:
        for t in tensors:
            if t.__class__ is not torch.Tensor:
                break
        else:
            return list(tensors)
    if not isinstance(tensors, (list, tuple)):
        raise TypeError(f"argument '{name}' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError(f"argument '{name}' must be tuple of Tensors")
    return list(tensors)


def same_length(a, b, what="tensor list"):
    if len(a) != len(b):
        raise RuntimeError(
            "Tensor list must have same number of elements as "
            f"{what}, got {len(a)} and {len(b)}"
        )


def promote(a, b):
    if a is b:
        return a
    try:
        return torch.promote_types(a, b)
    except Exception:
        return a


def out_shape(*tensors):
    shape = tensors[0].shape
    for t in tensors[1:]:
        if t.shape != shape:
            shape = broadcast_shapes(shape, t.shape)
    return shape


def broadcast_to(t, shape):
    if t.shape == shape:
        return t
    return t.expand(shape)


def broadcast_shapes(sa, sb):
    """Right-aligned shape broadcast; avoids a ``torch`` call from the host."""
    if sa == sb:
        return sa
    la, lb = len(sa), len(sb)
    out = []
    for i in range(max(la, lb)):
        da = int(sa[la - 1 - i]) if i < la else 1
        db = int(sb[lb - 1 - i]) if i < lb else 1
        if da == db or db == 1:
            out.append(da)
        elif da == 1:
            out.append(db)
        else:
            raise RuntimeError(
                f"shape {tuple(sa)} is not broadcastable with {tuple(sb)}"
            )
    return tuple(reversed(out))
